SELECT DATE_FORMAT(stores.opened_date, 'yyyy-MM') AS opened_month, SUM(CASE WHEN payments.status = 'REFUNDED' THEN payments.amount ELSE 0 END) AS refunded_amount FROM payments INNER JOIN orders ON payments.order_id = orders.id INNER JOIN stores ON orders.store_id = stores.id GROUP BY DATE_FORMAT(stores.opened_date, 'yyyy-MM') HAVING SUM(CASE WHEN payments.status = 'REFUNDED' THEN payments.amount ELSE 0 END) > 35 ORDER BY refunded_amount, opened_month LIMIT 10;
